  'ga_training_module_v1',
  $json${"schema_version":"1.0","module_id":"GA-A1-M01","kind":"training_module","format_profile":"ga_training_module_v1","level":"A1","sequence":1,"title":"Ankommen & Vorstellen","theme":"Se présenter et échanger des informations personnelles simples","subtitle":"Module d’entraînement A1 — German Academy (pas un examen blanc)","estimated_minutes":30,"prerequisites":[],"learning_objectives":["Saluer et prendre congé de façon appropriée","Dire son nom et épeler des lettres utiles","Indiquer pays, ville et langues parlées","Utiliser sein, heißen, kommen, wohnen, sprechen au présent","Poser et comprendre des questions avec wie, wo, woher, was","Comprendre un court texte et un dialogue oral sur la présentation","Produire une courte présentation écrite et orale"],"vocabulary_targets":["Guten Morgen","Guten Tag","Hallo","Tschüss","Auf Wiedersehen","Name","Land","Stadt","Sprache","Deutsch","Arabisch","Französisch","Studentin","Lehrer"],"grammar_targets":["sein (ich bin, Sie sind)","heißen","kommen aus","wohnen in","sprechen","Personalpronomen ich/du/Sie/wir","W-Fragen: wie, wo, woher, was"],"skills":["wortschatz","grammatik","lesen","hoeren","schreiben","sprechen","revision"],"publication_status":"draft","provenance":{"content_origin":"original","publisher_content_embedded":false,"commercial_media_used":false,"author":"German Academy","created_at":"2026-09-28","updated_at":"2026-09-28","version":"1.0.0"},"media":{"audio_tracks":[{"id":"GA-A1-M01-AUD-01","url":"/exam-media/ga-a1-m01/hoeren-vorstellen.mp3","duration_seconds":18,"script_staff_only":"Ansage: Hören Sie den Dialog. Mann: Guten Tag! Ich heiße Karim. Ich komme aus Algerien und wohne in Lyon. Frau: Schön! Ich heiße Nora. Ich spreche Deutsch und Französisch."}]},"correction":{"show_keys_before_submit":false,"allow_retry":true,"practice_scoring":true,"goethe_scoring":false,"pass_fail_certificate":false,"timed_exam":false},"activities":[{"id":"GA-A1-M01-W01","order":1,"skill":"wortschatz","activity_type":"single_choice","learning_objective":"Choisir une salutation adaptée au matin","theme":"Begrüßung","focus":"Guten Morgen / Gute Nacht / Auf Wiedersehen","difficulty":"guided","instruction":"Wählen Sie die passende Antwort.","prompt":"Es ist 8 Uhr morgens. Was sagt man?","points":1,"choices":[{"id":"A","text":"Gute Nacht"},{"id":"B","text":"Guten Morgen"},{"id":"C","text":"Auf Wiedersehen"}],"correct_answer":"B","explanation":"Le matin on dit « Guten Morgen ».","positive_feedback":"Très bien — salutation du matin correcte.","common_error":"« Gute Nacht » est pour le soir ; « Auf Wiedersehen » sert à prendre congé."},{"id":"GA-A1-M01-W02","order":2,"skill":"wortschatz","activity_type":"single_choice","learning_objective":"Distinguer prise de congé et salutation","theme":"Abschied","focus":"Tschüss / Hallo / Bitte","difficulty":"guided","instruction":"Wählen Sie die passende Antwort.","prompt":"Sie gehen nach Hause. Was sagen Sie zu einem Freund?","points":1,"choices":[{"id":"A","text":"Hallo"},{"id":"B","text":"Bitte"},{"id":"C","text":"Tschüss"}],"correct_answer":"C","explanation":"« Tschüss » est une prise de congé informelle.","positive_feedback":"Parfait — vous prenez congé correctement.","common_error":"« Hallo » sert à saluer, pas à partir."},{"id":"GA-A1-M01-G01","order":3,"skill":"grammatik","activity_type":"single_choice","learning_objective":"Conjuguer heißen avec Sie (forme de politesse)","theme":"Name sagen","focus":"heißen — Sie heißen","difficulty":"guided","instruction":"Ergänzen Sie das Verb.","prompt":"Wie ___ Sie?","points":1,"choices":[{"id":"A","text":"heißen"},{"id":"B","text":"heißt"},{"id":"C","text":"heiße"}],"correct_answer":"A","explanation":"Avec « Sie » : Wie heißen Sie? (pas heißt).","positive_feedback":"Exact — forme de politesse correcte.","common_error":"« heißt » va avec er/sie/es ou du, pas avec Sie."},{"id":"GA-A1-M01-G02","order":4,"skill":"grammatik","activity_type":"form_fill","learning_objective":"Utiliser sein (ich bin / Sie sind)","theme":"Beruf / Status","focus":"sein","difficulty":"semi_guided","instruction":"Ergänzen Sie die Formen von « sein ».","prompt":"Ich ___ Studentin. Und Sie? ___ Sie Lehrer?","points":2,"fields":[{"id":"1","label":"Lücke 1"},{"id":"2","label":"Lücke 2"}],"correct_form":{"1":"bin","2":"Sind"},"explanation":"ich bin ; question de politesse : Sind Sie … ?","positive_feedback":"Bravo — sein est bien conjugué.","common_error":"Attention à la majuscule de « Sind » en début de phrase."},{"id":"GA-A1-M01-G03","order":5,"skill":"grammatik","activity_type":"single_choice","learning_objective":"Exprimer la provenance avec kommen + woher","theme":"Herkunft","focus":"kommen / woher","difficulty":"guided","instruction":"Wählen Sie die richtige Verbform.","prompt":"Woher ___ du?","points":1,"choices":[{"id":"A","text":"kommst"},{"id":"B","text":"komme"},{"id":"C","text":"kommen"}],"correct_answer":"A","explanation":"Avec du : Woher kommst du?","positive_feedback":"Oui — conjugaison du correcte.","common_error":"Ne répétez pas « du » dans le trou : la question contient déjà « du »."},{"id":"GA-A1-M01-G04","order":6,"skill":"grammatik","activity_type":"single_choice","learning_objective":"Dire où l’on habite avec wohnen + wo","theme":"Wohnort","focus":"wohnen / wo","difficulty":"guided","instruction":"Wählen Sie die passende Antwort.","prompt":"___ wohnen Sie? — In Casablanca.","points":1,"choices":[{"id":"A","text":"Was"},{"id":"B","text":"Wo"},{"id":"C","text":"Woher"}],"correct_answer":"B","explanation":"« Wo » demande le lieu ; « Woher » demande la provenance.","positive_feedback":"Très juste — Wo pour le lieu d’habitation.","common_error":"« Woher » = d’où venez-vous, pas où habitez-vous."},{"id":"GA-A1-M01-G05","order":7,"skill":"grammatik","activity_type":"single_choice","learning_objective":"Indiquer les langues parlées avec sprechen","theme":"Sprachen","focus":"sprechen","difficulty":"semi_guided","instruction":"Wählen Sie die richtige Verbform.","prompt":"Ich ___ Arabisch und ein bisschen Deutsch.","points":1,"choices":[{"id":"A","text":"spreche"},{"id":"B","text":"spricht"},{"id":"C","text":"sprechen"}],"correct_answer":"A","explanation":"ich spreche …","positive_feedback":"Parfait — sprechen au présent avec ich.","common_error":"« spricht » est pour er/sie/es."},{"id":"GA-A1-M01-L01","order":8,"skill":"lesen","activity_type":"true_false","learning_objective":"Repérer une information factuelle dans un texte A1","theme":"Kurze Vorstellung lesen","focus":"Herkunft vs Wohnort","difficulty":"semi_guided","instruction":"Lesen Sie den Text. Ist der Satz richtig oder falsch?","passage":"Hallo! Ich heiße Leila. Ich bin 23 Jahre alt und komme aus Tunesien. Ich wohne jetzt in Marseille. Ich bin Studentin. Ich spreche Arabisch, Französisch und ein bisschen Deutsch.","prompt":"Leila kommt aus Marseille.","points":1,"choices":[{"id":"true","text":"Richtig"},{"id":"false","text":"Falsch"}],"correct_answer":false,"explanation":"Elle vient de Tunisie ; elle habite à Marseille.","positive_feedback":"Bien lu — vous séparez provenance et lieu de vie.","common_error":"Ne confondez pas « kommen aus » et « wohnen in »."},{"id":"GA-A1-M01-H01","order":9,"skill":"hoeren","activity_type":"listening","learning_objective":"Comprendre le nom dans un dialogue de présentation","theme":"Dialog Vorstellen","focus":"Name hören","difficulty":"semi_guided","instruction":"Hören Sie den Dialog. Wählen Sie die richtige Antwort.","prompt":"Wie heißt der Mann?","points":1,"choices":[{"id":"A","text":"Karim"},{"id":"B","text":"Nora"},{"id":"C","text":"Samir"}],"correct_answer":"A","explanation":"Le homme dit : Ich heiße Karim.","positive_feedback":"Bonne écoute — nom bien repéré.","common_error":"Nora est le nom de la femme dans le dialogue.","media":{"audio_url":"/exam-media/ga-a1-m01/hoeren-vorstellen.mp3","audio_script_staff_only":"Ansage: Hören Sie den Dialog. Mann: Guten Tag! Ich heiße Karim. Ich komme aus Algerien und wohne in Lyon. Frau: Schön! Ich heiße Nora. Ich spreche Deutsch und Französisch.","duration_seconds":18}},{"id":"GA-A1-M01-H02","order":10,"skill":"hoeren","activity_type":"listening","learning_objective":"Comprendre la ville de résidence dans le dialogue","theme":"Dialog Vorstellen","focus":"Wohnort hören","difficulty":"semi_guided","instruction":"Hören Sie noch einmal. Wählen Sie die richtige Antwort.","prompt":"Wo wohnt Karim?","points":1,"choices":[{"id":"A","text":"In Algerien"},{"id":"B","text":"In Lyon"},{"id":"C","text":"In Tunis"}],"correct_answer":"B","explanation":"Il dit : ich wohne in Lyon. Algerien est sa provenance.","positive_feedback":"Très bien — vous distinguez woher et wo.","common_error":"« aus Algerien » = provenance, pas le lieu d’habitation.","media":{"audio_url":"/exam-media/ga-a1-m01/hoeren-vorstellen.mp3","audio_script_staff_only":"Ansage: Hören Sie den Dialog. Mann: Guten Tag! Ich heiße Karim. Ich komme aus Algerien und wohne in Lyon. Frau: Schön! Ich heiße Nora. Ich spreche Deutsch und Französisch.","duration_seconds":18}},{"id":"GA-A1-M01-S01","order":11,"skill":"schreiben","activity_type":"writing","learning_objective":"Écrire une courte présentation personnelle A1","theme":"Selbstvorstellung schreiben","focus":"Name, Herkunft, Wohnort, Sprachen","difficulty":"autonomous","instruction":"Schreiben Sie 4–6 kurze Sätze.","prompt":"Stellen Sie sich vor: Name, Alter, Herkunft, Wohnort, Sprachen. Schreiben Sie auf Deutsch.","points":4,"recommended_words":35,"sample_answer_staff_only":"Ich heiße Samira. Ich bin 21 Jahre alt. Ich komme aus Marokko und wohne in Paris. Ich spreche Arabisch und Französisch. Ich lerne Deutsch.","rubric":[{"id":"task_completion","label":"Tâche remplie (infos demandées)","max_points":2},{"id":"vocabulary","label":"Vocabulaire adapté A1","max_points":1},{"id":"grammar_and_spelling","label":"Structures simples compréhensibles","max_points":1}],"auto_grade_as_certain":false,"positive_feedback":"Merci — votre texte sera relu par un enseignant.","common_error":"Évitez les phrases trop longues ; une idée par phrase suffit."},{"id":"GA-A1-M01-O01","order":12,"skill":"sprechen","activity_type":"speaking","learning_objective":"Produire oralement une mini-présentation et épeler son prénom","theme":"Mündlich vorstellen","focus":"Sprechen + buchstabieren","difficulty":"autonomous","instruction":"Sprechen Sie laut. Sie können aufnehmen oder üben ohne Mikrofon.","prompt":"Stellen Sie sich vor und buchstabieren Sie Ihren Vornamen.","points":4,"speaking_card":"1) Begrüßung  2) Name  3) Woher / wo  4) Sprachen  5) Vornamen buchstabieren (A, B, C …)","sample_answer_staff_only":"Guten Tag! Ich heiße Omar. Ich komme aus Ägypten und wohne in Bordeaux. Ich spreche Arabisch und Französisch. Mein Name: O-M-A-R.","rubric":[{"id":"task_completion","label":"Points de la carte couverts","max_points":2},{"id":"intelligibility","label":"Intelligibilité","max_points":1},{"id":"structures","label":"Structures A1 (heißen, kommen, wohnen, sprechen)","max_points":1}],"mic_fallback":"Si le micro est refusé : entraînez-vous à voix haute avec la carte, puis validez « pratiqué sans enregistrement ».","auto_grade_as_certain":false,"positive_feedback":"Bon entraînement oral — un enseignant pourra commenter l’enregistrement.","common_error":"Parlez lentement ; épeler lettre par lettre suffit."},{"id":"GA-A1-M01-R01","order":13,"skill":"revision","activity_type":"single_choice","learning_objective":"Réviser la distinction wo / woher / wie","theme":"Abschluss-Revision","focus":"W-Fragen","difficulty":"autonomous","instruction":"Kurze Revision. Wählen Sie die richtige Frage.","prompt":"Sie möchten den Namen wissen. Was fragen Sie?","points":1,"choices":[{"id":"A","text":"Wo wohnen Sie?"},{"id":"B","text":"Wie heißen Sie?"},{"id":"C","text":"Woher kommen Sie?"}],"correct_answer":"B","explanation":"Pour le nom : Wie heißen Sie?","positive_feedback":"Révision réussie — bonne question pour le nom.","common_error":"Wo = lieu ; Woher = provenance ; Wie heißen = nom."}]}$json$::jsonb,
